problems.acmCode:
# ACM 模式：完整可运行程序（stdin -> stdout）
# 输入格式：一行，二叉树的层序序列，空节点用 null 表示（如 "1 null 2 3"）
# 输出格式：一行，中序遍历结果，形如 [1,3,2]（空树输出 []）
import sys
from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build(tokens):
    """按层序 token 流构造二叉树，'null' 表示空节点。"""
    if not tokens or tokens[0] == 'null':
        return None
    root = TreeNode(int(tokens[0]))
    q, i = deque([root]), 1
    while q and i < len(tokens):
        node = q.popleft()
        if i < len(tokens):
            if tokens[i] != 'null':
                node.left = TreeNode(int(tokens[i]))
                q.append(node.left)
            i += 1
        if i < len(tokens):
            if tokens[i] != 'null':
                node.right = TreeNode(int(tokens[i]))
                q.append(node.right)
            i += 1
    return root


def to_level(root):
    """层序带 null 序列化（裁剪末尾多余 null）。"""
    if not root:
        return '[]'
    res, q = [], deque([root])
    while q:
        node = q.popleft()
        if node:
            res.append(str(node.val))
            q.append(node.left)
            q.append(node.right)
        else:
            res.append('null')
    while res and res[-1] == 'null':
        res.pop()
    return '[' + ','.join(res) + ']' 


class Solution:
    def inorderTraversal(self, root):
        res, stack = [], []
        cur = root
        while cur or stack:
            while cur:              # 一路向左压栈
                stack.append(cur)
                cur = cur.left
            cur = stack.pop()       # 弹出最左的未访问节点
            res.append(cur.val)     # 收集
            cur = cur.right         # 转向右子树
        return res


def main():
    root = build(sys.stdin.read().split())
    res = Solution().inorderTraversal(root)
    print('[' + ','.join(map(str, res)) + ']')


if __name__ == '__main__':
    main()

