// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：一行，二叉树的层序序列，空节点用 null 表示（如 "1 null 2 3"；空树为空行）
// 输出格式：一行，中序遍历结果，形如 [1,3,2]（空树输出 []）
#include <bits/stdc++.h>
using namespace std;

// 二叉树节点定义（ACM 模式需自带）
struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

// 把一行按空白切成 token
vector<string> splitTokens(const string& line) {
    vector<string> tokens;
    istringstream iss(line);
    string tok;
    while (iss >> tok) tokens.push_back(tok);
    return tokens;
}

// 按层序 token 流建树：'null' 表示空节点
TreeNode* build(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;   // 空树
    TreeNode* root = new TreeNode(stoi(tokens[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < tokens.size()) {    // 逐个出队，依次挂左右孩子
        TreeNode* node = q.front();
        q.pop();
        if (i < tokens.size()) {                 // 先挂左孩子
            if (tokens[i] != "null") {
                node->left = new TreeNode(stoi(tokens[i]));
                q.push(node->left);
            }
            ++i;
        }
        if (i < tokens.size()) {                 // 再挂右孩子
            if (tokens[i] != "null") {
                node->right = new TreeNode(stoi(tokens[i]));
                q.push(node->right);
            }
            ++i;
        }
    }
    return root;
}

class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> res;
        stack<TreeNode*> st;
        TreeNode* cur = root;
        while (cur || !st.empty()) {
            while (cur) {                 // 第一步：一路向左，沿途节点全部压栈
                st.push(cur);
                cur = cur->left;
            }
            cur = st.top();               // 第二步：弹出最左的未访问节点
            st.pop();
            res.push_back(cur->val);      // 收集
            cur = cur->right;             // 第三步：转向右子树，重复『向左入栈』
        }
        return res;
    }
};

int main() {
    string line;
    getline(cin, line);                     // 一行：层序序列（空行即空树）
    TreeNode* root = build(splitTokens(line));
    vector<int> res = Solution().inorderTraversal(root);
    string out = "[";
    for (size_t i = 0; i < res.size(); ++i) {
        if (i) out += ',';
        out += to_string(res[i]);
    }
    cout << out << ']' << '\n';
    return 0;
}

