func inorderTraversal(root *TreeNode) []int {
	res := []int{}
	stack := []*TreeNode{}
	cur := root
	for cur != nil || len(stack) > 0 {
		for cur != nil { // 第一步：一路向左，沿途节点全部入栈
			stack = append(stack, cur)
			cur = cur.Left
		}
		cur = stack[len(stack)-1] // 第二步：弹出最左的未访问节点
		stack = stack[:len(stack)-1]
		res = append(res, cur.Val) // 收集
		cur = cur.Right            // 第三步：转向右子树，重复『向左入栈』
	}
	return res
}

