class Solution:
    def maxDepth(self, root: Optional[TreeNode]) -> int:
        def dfs(node: Optional[TreeNode]) -> int:
            # 递归基线：空树深度为 0
            if not node:
                return 0
            # 分治：先分别递归求出左右子树的最大深度
            left = dfs(node.left)
            right = dfs(node.right)
            # 汇总：整棵树深度 = max(左, 右) + 当前根这一层
            return max(left, right) + 1
        # 从根节点开始递归
        return dfs(root)

