class Solution:
    def maxDepth(self, root):
        def dfs(node):
            if not node:
                return 0                    # 基线：空树深度 0
            left = dfs(node.left)           # 左子树深度
            right = dfs(node.right)         # 右子树深度
            return max(left, right) + 1     # 汇总：当前层 +1

        return dfs(root)


