class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def show(root):
    """层序带 null 序列化（裁剪末尾多余 null），便于自测观察。"""
    if not root:
        return '[]'
    res, q = [], [root]
    while q:
        node = q.pop(0)
        if node:
            res.append(str(node.val))
            q.append(node.left)
            q.append(node.right)
        else:
            res.append('null')
    while res and res[-1] == 'null':
        res.pop()
    return '[' + ','.join(res) + ']' 

def build_tree_scan(preorder, inorder):
    """前序 + 中序构造：每层线性扫描定位根（无哈希）。"""
    pre_idx = 0

    def dfs(in_l, in_r):
        nonlocal pre_idx
        if in_l > in_r:
            return None
        root_val = preorder[pre_idx]
        pre_idx += 1
        mid = in_l
        while inorder[mid] != root_val:    # 在区间内线性扫描找根
            mid += 1
        root = TreeNode(root_val)
        root.left = dfs(in_l, mid - 1)     # 先左后右
        root.right = dfs(mid + 1, in_r)
        return root

    return dfs(0, len(inorder) - 1)


# 自测
print(show(build_tree_scan([3, 9, 20, 15, 7], [9, 3, 15, 20, 7])))  # [3,9,20,null,null,15,7]

