class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        # 哈希表：值 -> 中序下标，O(1) 定位根在中序中的切分点
        pos = {}
        for i, v in enumerate(inorder):
            pos[v] = i
        self.preIdx = 0  # 全局指针：当前待消费的根在前序中的位置

        def dfs(inL: int, inR: int) -> Optional[TreeNode]:
            # 中序区间为空，说明这棵子树不存在
            if inL > inR:
                return None
            # 前序当前值就是这棵子树的根（前序：根-左-右）
            root = TreeNode(preorder[self.preIdx])
            self.preIdx += 1
            mid = pos[root.val]
            # 必须先建左子树再建右子树，与前序的消费顺序一致
            root.left = dfs(inL, mid - 1)
            root.right = dfs(mid + 1, inR)
            return root

        return dfs(0, len(inorder) - 1)

