# ACM 模式：完整可运行程序（stdin -> stdout）
# 输入格式：两行：第一行 preorder，第二行 inorder，均空格分隔（如 "3 9 20 15 7" / "9 3 15 20 7"）
# 输出格式：一行，构造出的二叉树层序序列，形如 [3,9,20,null,null,15,7]
import sys
from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build(tokens):
    """按层序 token 流构造二叉树，'null' 表示空节点。"""
    if not tokens or tokens[0] == 'null':
        return None
    root = TreeNode(int(tokens[0]))
    q, i = deque([root]), 1
    while q and i < len(tokens):
        node = q.popleft()
        if i < len(tokens):
            if tokens[i] != 'null':
                node.left = TreeNode(int(tokens[i]))
                q.append(node.left)
            i += 1
        if i < len(tokens):
            if tokens[i] != 'null':
                node.right = TreeNode(int(tokens[i]))
                q.append(node.right)
            i += 1
    return root


def to_level(root):
    """层序带 null 序列化（裁剪末尾多余 null）。"""
    if not root:
        return '[]'
    res, q = [], deque([root])
    while q:
        node = q.popleft()
        if node:
            res.append(str(node.val))
            q.append(node.left)
            q.append(node.right)
        else:
            res.append('null')
    while res and res[-1] == 'null':
        res.pop()
    return '[' + ','.join(res) + ']' 


class Solution:
    def buildTree(self, preorder, inorder):
        pos = {v: i for i, v in enumerate(inorder)}   # 值 -> 中序下标
        pre_idx = 0

        def dfs(in_l, in_r):
            nonlocal pre_idx
            if in_l > in_r:                    # 区间为空：子树不存在
                return None
            root = TreeNode(preorder[pre_idx]) # 前序当前值即根
            pre_idx += 1
            mid = pos[root.val]
            root.left = dfs(in_l, mid - 1)     # 先左后右
            root.right = dfs(mid + 1, in_r)
            return root

        return dfs(0, len(inorder) - 1)


def main():
    lines = sys.stdin.read().splitlines()
    preorder = [int(x) for x in lines[0].split()]
    inorder = [int(x) for x in lines[1].split()]
    print(to_level(Solution().buildTree(preorder, inorder)))


if __name__ == '__main__':
    main()

