class Solution {
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        unordered_map<int, int> pos;               // 哈希表：值 -> 中序下标，O(1) 定位切分点
        for (int i = 0; i < (int)inorder.size(); ++i) pos[inorder[i]] = i;
        int preIdx = 0;                            // 全局指针：当前待消费的根在前序中的位置
        function<TreeNode*(int, int)> dfs = [&](int inL, int inR) -> TreeNode* {
            if (inL > inR) return nullptr;         // 中序区间为空：这棵子树不存在
            TreeNode* root = new TreeNode(preorder[preIdx++]);  // 前序当前值就是子树根
            int mid = pos[root->val];
            root->left = dfs(inL, mid - 1);        // 必须先建左子树再建右子树，与前序消费顺序一致
            root->right = dfs(mid + 1, inR);
            return root;
        };
        return dfs(0, (int)inorder.size() - 1);
    }
};

