def build_tree_scan(inorder, postorder):
    """中序 + 后序构造：线性扫描定位根（无哈希）。"""
    post_idx = len(postorder) - 1

    def dfs(in_l, in_r):
        nonlocal post_idx
        if in_l > in_r:
            return None
        root_val = postorder[post_idx]
        post_idx -= 1
        mid = in_l
        while inorder[mid] != root_val:    # 区间内线性扫描找根
            mid += 1
        root = TreeNode(root_val)
        root.right = dfs(mid + 1, in_r)    # 先右后左
        root.left = dfs(in_l, mid - 1)
        return root

    return dfs(0, len(inorder) - 1)


