TreeNode* build(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;   // 空树
    TreeNode* root = new TreeNode(stoi(tokens[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < tokens.size()) {    // 逐个出队，依次挂左右孩子
        TreeNode* node = q.front();
        q.pop();
        if (i < tokens.size()) {                 // 先挂左孩子
            if (tokens[i] != "null") {
                node->left = new TreeNode(stoi(tokens[i]));
                q.push(node->left);
            }
            ++i;
        }
        if (i < tokens.size()) {                 // 再挂右孩子
            if (tokens[i] != "null") {
                node->right = new TreeNode(stoi(tokens[i]));
                q.push(node->right);
            }
            ++i;
        }
    }
    return root;
}

class Solution {
public:
    int minDepth(TreeNode* root) {
        if (!root) return 0;                        // 情况 0：空树深度为 0
        if (!root->left && !root->right) return 1;  // 情况 1：叶子节点深度为 1
        if (!root->left)                            // 情况 2：缺左子树，只能往右走
            return minDepth(root->right) + 1;       // （不能取 min，否则错把空侧当捷径）
        if (!root->right)                           // 情况 3：缺右子树，同理往左走
            return minDepth(root->left) + 1;
        // 情况 4：两侧齐全，取较小深度 + 1
        return min(minDepth(root->left), minDepth(root->right)) + 1;
    }
};

int main() {
    string line;
    getline(cin, line);                     // 一行：层序序列（空行即空树）
    TreeNode* root = build(splitTokens(line));
    cout << Solution().minDepth(root) << '\n';
    return 0;
}

