# ACM 模式：完整可运行程序（stdin -> stdout）
# 输入格式：一行，二叉树的层序序列，空节点用 null 表示（如 "1 2 5 3 4 null 6"）
# 输出格式：一行，展开后链表的层序序列，形如 [1,null,2,null,3,null,4,null,5,null,6]
import sys
from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build(tokens):
    """按层序 token 流构造二叉树，'null' 表示空节点。"""
    if not tokens or tokens[0] == 'null':
        return None
    root = TreeNode(int(tokens[0]))
    q, i = deque([root]), 1
    while q and i < len(tokens):
        node = q.popleft()
        if i < len(tokens):
            if tokens[i] != 'null':
                node.left = TreeNode(int(tokens[i]))
                q.append(node.left)
            i += 1
        if i < len(tokens):
            if tokens[i] != 'null':
                node.right = TreeNode(int(tokens[i]))
                q.append(node.right)
            i += 1
    return root


def to_level(root):
    """层序带 null 序列化（裁剪末尾多余 null）。"""
    if not root:
        return '[]'
    res, q = [], deque([root])
    while q:
        node = q.popleft()
        if node:
            res.append(str(node.val))
            q.append(node.left)
            q.append(node.right)
        else:
            res.append('null')
    while res and res[-1] == 'null':
        res.pop()
    return '[' + ','.join(res) + ']' 


class Solution:
    def flatten(self, root):
        # 原地前驱三步法：找衔接点 -> 接右 -> 搬左 -> 清左
        cur = root
        while cur:
            if cur.left:
                prev = cur.left
                while prev.right:       # 左子树沿 right 走到底
                    prev = prev.right
                prev.right = cur.right  # 右子树挂到衔接点后
                cur.right = cur.left    # 左子树搬到右边
                cur.left = None         # 清空左指针
            cur = cur.right


def main():
    root = build(sys.stdin.read().split())
    Solution().flatten(root)
    print(to_level(root))


if __name__ == '__main__':
    main()

