        if not node:
            return 0
        return node.val + max(down(node.left), down(node.right), 0)

    def walk(node):                    # 枚举折点
        if not node:
            return float('-inf')
        best = node.val + max(down(node.left), 0) + max(down(node.right), 0)
        return max(best, walk(node.left), walk(node.right))

    return walk(root)


