# ACM 模式：完整可运行程序（stdin -> stdout）
# 输入格式：一行，二叉树的层序序列，空节点用 null 表示（如 "-10 9 20 null null 15 7"）
# 输出格式：一行，最大路径和（整数）
import sys
from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build(tokens):
    """按层序 token 流构造二叉树，'null' 表示空节点。"""
    if not tokens or tokens[0] == 'null':
        return None
    root = TreeNode(int(tokens[0]))
    q, i = deque([root]), 1
    while q and i < len(tokens):
        node = q.popleft()
        if i < len(tokens):
            if tokens[i] != 'null':
                node.left = TreeNode(int(tokens[i]))
                q.append(node.left)
            i += 1
        if i < len(tokens):
            if tokens[i] != 'null':
                node.right = TreeNode(int(tokens[i]))
                q.append(node.right)
            i += 1
    return root


def to_level(root):
    """层序带 null 序列化（裁剪末尾多余 null）。"""
    if not root:
        return '[]'
    res, q = [], deque([root])
    while q:
        node = q.popleft()
        if node:
            res.append(str(node.val))
            q.append(node.left)
            q.append(node.right)
        else:
            res.append('null')
    while res and res[-1] == 'null':
        res.pop()
    return '[' + ','.join(res) + ']' 


class Solution:
    def maxPathSum(self, root):
        self.ans = float('-inf')            # 全局答案：-inf 应对全负树

        def dfs(node):
            # 空节点向上贡献 0
            if not node:
                return 0
            # 负臂用 0 舍弃：路径不进入该侧
            left = max(dfs(node.left), 0)
            right = max(dfs(node.right), 0)
            # 折点处双臂折叠，枚举以 node 为最高点的路径
            self.ans = max(self.ans, node.val + left + right)
            # 向父节点只能贡献一条臂
            return node.val + max(left, right)

        dfs(root)
        return self.ans


def main():
    root = build(sys.stdin.read().split())
    print(Solution().maxPathSum(root))


if __name__ == '__main__':
    main()

