from collections import deque


class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        # 右视图 = 每一层最右侧可见的节点，BFS 逐层收集
        if not root:
            return []
        res, q = [], deque([root])
        while q:
            # 先锁定本层节点数，之后入队的一定是下一层
            size = len(q)
            for i in range(size):
                node = q.popleft()
                # 本层最后一个出队的节点，就是右侧看到的那个
                if i == size - 1:
                    res.append(node.val)
                # 先左后右入队，保证出队顺序与层内从左到右一致
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
        return res

