            # 交换当前节点的左右指针（元组交换免临时变量）
            node.left, node.right = node.right, node.left
            # 再递归翻转交换后的左右子树
            dfs(node.left)
            dfs(node.right)
            # 返回翻转后的根，供上层拼接
            return node

        return dfs(root)


