# ACM 模式：完整可运行程序（stdin -> stdout）
# 输入格式：两行：第一行 BST 的层序序列（空节点用 null），第二行 k（如 "5 3 6 2 4 null null 1" / "3"）
# 输出格式：一行，第 k 小的元素值
import sys
from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build(tokens):
    """按层序 token 流构造二叉树，'null' 表示空节点。"""
    if not tokens or tokens[0] == 'null':
        return None
    root = TreeNode(int(tokens[0]))
    q, i = deque([root]), 1
    while q and i < len(tokens):
        node = q.popleft()
        if i < len(tokens):
            if tokens[i] != 'null':
                node.left = TreeNode(int(tokens[i]))
                q.append(node.left)
            i += 1
        if i < len(tokens):
            if tokens[i] != 'null':
                node.right = TreeNode(int(tokens[i]))
                q.append(node.right)
            i += 1
    return root


def to_level(root):
    """层序带 null 序列化（裁剪末尾多余 null）。"""
    if not root:
        return '[]'
    res, q = [], deque([root])
    while q:
        node = q.popleft()
        if node:
            res.append(str(node.val))
            q.append(node.left)
            q.append(node.right)
        else:
            res.append('null')
    while res and res[-1] == 'null':
        res.pop()
    return '[' + ','.join(res) + ']' 


class Solution:
    def kthSmallest(self, root, k):
        # 迭代中序：BST 中序即升序，数到第 k 个直接返回
        stack, cur = [], root
        while cur or stack:
            while cur:                  # 一路向左压栈
                stack.append(cur)
                cur = cur.left
            cur = stack.pop()           # 当前最小的未访问节点
            k -= 1
            if k == 0:
                return cur.val          # 提前终止
            cur = cur.right
        return -1                       # 题目保证 k 合法，兜底而已


def main():
    lines = sys.stdin.read().splitlines()
    root = build(lines[0].split())
    k = int(lines[1].split()[0])
    print(Solution().kthSmallest(root, k))


if __name__ == '__main__':
    main()

