// 按层序 token 流建树：'null' 表示空节点
TreeNode* build(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;   // 空树
    TreeNode* root = new TreeNode(stoi(tokens[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < tokens.size()) {    // 逐个出队，依次挂左右孩子
        TreeNode* node = q.front();
        q.pop();
        if (i < tokens.size()) {                 // 先挂左孩子
            if (tokens[i] != "null") {
                node->left = new TreeNode(stoi(tokens[i]));
                q.push(node->left);
            }
            ++i;
        }
        if (i < tokens.size()) {                 // 再挂右孩子
            if (tokens[i] != "null") {
                node->right = new TreeNode(stoi(tokens[i]));
                q.push(node->right);
            }
            ++i;
        }
    }
    return root;
}

// 按值查找节点（题目保证值唯一）
TreeNode* findNode(TreeNode* root, int v) {
    if (!root) return nullptr;
    if (root->val == v) return root;
    TreeNode* l = findNode(root->left, v);
    return l ? l : findNode(root->right, v);
}

class Solution {
public:
    // 后序遍历：空或命中 p/q 之一时，命中结果直接向上返回
    TreeNode* dfs(TreeNode* node, TreeNode* p, TreeNode* q) {
        if (!node || node == p || node == q) return node;  // 命中即可停止下探
        TreeNode* left = dfs(node->left, p, q);    // 先在左右子树里分别找 p 和 q
        TreeNode* right = dfs(node->right, p, q);
        if (left && right) return node;            // 左右各命中一个：当前 node 就是 LCA
        return left ? left : right;                // 单侧命中（含 p 是 q 祖先）：向上透传
    }
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        return dfs(root, p, q);
    }
};

