    getline(cin, line2);                   // 第二行：p q
    TreeNode* root = build(splitTokens(line1));
    vector<string> pq = splitTokens(line2);
    TreeNode* p = findNode(root, stoi(pq[0]));
    TreeNode* q = findNode(root, stoi(pq[1]));
