        self.right = right

def build(vals):
    """按层序数组（None 表示空节点）构造二叉树，便于自测。"""
    if not vals:
        return None
    root = TreeNode(vals[0])
    q, i = [root], 1
    while q and i < len(vals):
        node = q.pop(0)
        if vals[i] is not None:                    # 左孩子
            node.left = TreeNode(vals[i])
            q.append(node.left)
        i += 1
        if i < len(vals) and vals[i] is not None:  # 右孩子
            node.right = TreeNode(vals[i])
            q.append(node.right)
        i += 1
    return root

def lowestCommonAncestor(root, p, q):
    def dfs(node):
        if not node or node is p or node is q:
            return node                    # 空或命中即停
        left = dfs(node.left)
        right = dfs(node.right)
        if left and right:
            return node                    # 双命中：当前即 LCA
        return left if left else right     # 单命中透传

    return dfs(root)


def find(node, v):
    if not node:
        return None
    if node.val == v:
        return node
    return find(node.left, v) or find(node.right, v)


