TreeNode* build(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;   // 空树
    TreeNode* root = new TreeNode(stoi(tokens[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
