class Codec {
    // 前序序列化：根-左-右；空节点用 '#' 占位，否则无法唯一还原
    public String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        serDfs(root, sb);
        if (sb.length() > 0) sb.deleteCharAt(sb.length() - 1);  // 去掉末尾多余的逗号
        return sb.toString();
    }

