    public TreeNode deserialize(String data) {
        Queue<String> tokens = new LinkedList<>(Arrays.asList(data.split(",")));
        return desDfs(tokens);
    }

    private TreeNode desDfs(Queue<String> tokens) {
        String val = tokens.poll();             // 逐个消费 token
        if (val.equals("#")) return null;       // '#' 是空节点标记，还原为 null
        TreeNode node = new TreeNode(Integer.parseInt(val));  // 先建根
        node.left = desDfs(tokens);             // 再按前序顺序建左子树
        node.right = desDfs(tokens);            // 后建右子树
        return node;
