/**
 * 将二叉树编码为单个字符串（前序 + '#' 空标记）
 * @param {TreeNode} root
 * @return {string}
 */
var serialize = function (root) {
  const res = [];
  const dfs = (node) => {
    if (!node) { res.push('#'); return; }  // 空节点用 '#' 占位，否则无法唯一还原
    res.push(String(node.val));            // 先根
    dfs(node.left);                        // 再左子树
    dfs(node.right);                       // 后右子树
  };
  dfs(root);
  return res.join(',');                    // 逗号拼接成单个字符串（负数、多位数都没问题）
};

/**
 * 将字符串解码回二叉树（token 流按前序消费，免维护下标）
 * @param {string} data
 * @return {TreeNode}
 */
var deserialize = function (data) {
  const tokens = data.split(',');          // 切成 token 流
  let idx = 0;
  const dfs = () => {
    const val = tokens[idx++];             // 逐个消费 token
    if (val === '#') return null;          // '#' 是空节点标记，还原为 null
    const node = new TreeNode(Number(val));  // 先建根
    node.left = dfs();                     // 再按前序顺序建左子树
    node.right = dfs();                    // 后建右子树
    return node;
  };
  return dfs();
};

