// 整数转十进制字符串（不写 import，手动实现替代 strconv）
func itoa(x int) string {
	if x == 0 {
		return "0" // 特判零
	}
	neg := x < 0
	if neg {
		x = -x // 先转正，逐位取余
	}
	var buf [12]byte
	i := len(buf)
	for x > 0 {
		i--
		buf[i] = byte('0' + x%10) // 从低位往高位填
		x /= 10
	}
	if neg {
		i--
		buf[i] = '-' // 负号放最前
	}
	return string(buf[i:])
}

// 前序序列化：根-左-右；空节点用 '#' 占位，否则无法唯一还原
func serialize(root *TreeNode) string {
	res := []string{}
	var dfs func(node *TreeNode)
	dfs = func(node *TreeNode) {
		if node == nil {
			res = append(res, "#") // 空标记
			return
		}
		res = append(res, itoa(node.Val)) // 先根
		dfs(node.Left)                    // 再左子树
		dfs(node.Right)                   // 后右子树
	}
	dfs(root)
	out := ""                       // 逗号拼接成单个字符串
	for i, p := range res {
		if i > 0 {
			out += ","
		}
		out += p
	}
	return out
}

// 切成 token 流，按前序顺序消费，免维护下标
func deserialize(data string) *TreeNode {
	tokens := []string{} // 手动按逗号切分（不写 import，替代 strings.Split）
	start := 0
	for i := 0; i <= len(data); i++ {
		if i == len(data) || data[i] == ',' {
			tokens = append(tokens, data[start:i])
			start = i + 1
		}
	}
	pos := 0
	var dfs func() *TreeNode
	dfs = func() *TreeNode {
		val := tokens[pos] // 逐个消费 token
		pos++
		if val == "#" {
			return nil // '#' 是空节点标记，还原为 nil
		}
		v, neg := 0, false // 手动解析整数（支持负数）
		for _, c := range val {
			if c == '-' {
				neg = true
				continue
			}
			v = v*10 + int(c-'0')
		}
		if neg {
			v = -v
		}
		node := &TreeNode{Val: v} // 先建根
		node.Left = dfs()         // 再按前序顺序建左子树
		node.Right = dfs()        // 后建右子树
		return node
	}
	return dfs()
}
